// Expected: { lead_id, diagnostic_id, schema_id }
const input = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};
if (headers['x-webhook-secret'] !== $vars.WEBHOOK_SECRET) {
  throw new Error('Unauthorized');
}
for (const k of ['lead_id', 'diagnostic_id', 'schema_id']) {
  if (!input[k]) throw new Error(`Missing: ${k}`);
}
return [{ json: { lead_id: input.lead_id, diagnostic_id: input.diagnostic_id, schema_id: input.schema_id } }];

// Merge diagnostic + schema URL into a single context for the prompt.
const diagRows = $('Fetch diagnostic').first().json;
const diagRow = Array.isArray(diagRows) ? diagRows[0] : diagRows;
const schemaRows = $input.first().json;
const schemaRow = Array.isArray(schemaRows) ? schemaRows[0] : schemaRows;

if (!diagRow) throw new Error('Diagnostic not found');
if (!schemaRow || !schemaRow.public_url) throw new Error('Schema URL missing');

const lead = diagRow.consulting_leads || {};
const diag = diagRow.raw_response || {};
const task1 = (diag.tasks || [])[0] || {};

return [{
  json: {
    lead_id: diagRow.lead_id,
    diagnostic_id: diagRow.id,
    schema_id: $('Validate input').first().json.schema_id,
    business_name: lead.business_name,
    sector: lead.business_sector,
    task_1_name: task1.name,
    task_1_hours: task1.hours_lost_weekly,
    pitch_hook: diag.pitch_hook,
    schema_url: schemaRow.public_url
  }
}];

const response = $input.first().json;
const ctx = $('Merge context').first().json;

let text;
try { text = response.content[0].text; }
catch (e) { throw new Error('Claude response missing content[0].text'); }

text = text.trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '');

let parsed;
try { parsed = JSON.parse(text); }
catch (e) { throw new Error('Pitcher returned non-JSON: ' + text.slice(0, 300)); }

if (!parsed.email || !parsed.dm) {
  throw new Error('Missing email or dm in pitcher output');
}

const usage = response.usage || {};
const inTok = usage.input_tokens || 0;
const outTok = usage.output_tokens || 0;
const costUsd = (inTok / 1e6) * 3 + (outTok / 1e6) * 15;

// Emit one item per channel — Supabase will insert both in the next batch.
return [
  {
    json: {
      lead_id: ctx.lead_id,
      diagnostic_id: ctx.diagnostic_id,
      schema_id: ctx.schema_id,
      channel: 'email',
      body: parsed.email,
      tokens_in: inTok,
      tokens_out: outTok,
      api_cost_usd: Number(costUsd.toFixed(4))
    }
  },
  {
    json: {
      lead_id: ctx.lead_id,
      diagnostic_id: ctx.diagnostic_id,
      schema_id: ctx.schema_id,
      channel: 'instagram',
      body: parsed.dm,
      tokens_in: 0,
      tokens_out: 0,
      api_cost_usd: 0
    }
  }
];
